1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code customerCode}, formatted {@code <LAST3>-<NNNN>} where LAST3 is the
9	 * upper-cased first three letters of lastName and NNNN is a global 4-digit zero-padded sequence
10	 * equal to one more than the current number of owners (e.g. {@code SMI-0007}).
11	 */
12	public class AssignCustomerCode {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
15	        String lastName = owner.getLastName();
16	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
17	        int sequence = ownerRepository.findAll().size() + 1;
18	        owner.setCustomerCode(String.format("%s-%04d", last3, sequence));
19	    }
20	}
