15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
25	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
26	    OwnerDto toOwnerDto(Owner owner);
27	
28	    default String initials(Owner owner) {
29	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
30	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
31	    }
32	
33	    /**
34	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the last two
35	     * digits of the registrationDate year (e.g. {@code SMI-0007-M26}). Null when either the customer
36	     * code or the registration date is absent.
37	     */
38	    default String membershipNumber(Owner owner) {
39	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
40	            return null;
41	        }
42	        return String.format("%s-M%02d", owner.getCustomerCode(),
43	                owner.getRegistrationDate().getYear() % 100);
44	    }
45	
46	    /**
47	     * The owner's membership tier: {@code SILVER} when the owner's name was unique on creation
48	     * (namesakeCount is 0) and an email is present, otherwise {@code BRONZE}.
49	     */
50	    default OwnerDto.MembershipTierEnum membershipTier(Owner owner) {
51	        Integer namesakeCount = owner.getNamesakeCount();
52	        boolean unique = namesakeCount != null && namesakeCount == 0;
53	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
54	        return unique && hasEmail ? OwnerDto.MembershipTierEnum.SILVER
55	                : OwnerDto.MembershipTierEnum.BRONZE;
56	    }
57	
58	    Owner toOwner(OwnerDto ownerDto);
59	
60	    @Mapping(target = "id", ignore = true)
61	    @Mapping(target = "pets", ignore = true)
62	    Owner toOwner(OwnerFieldsDto ownerDto);
63	
64	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
65	
66	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
67	
68	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
69	        OwnerPageDto ownerPageDto = new OwnerPageDto();
70	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
71	        ownerPageDto.setPage(ownerPage.getNumber());
72	        ownerPageDto.setSize(ownerPage.getSize());
73	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
74	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
75	        return ownerPageDto;
76	    }
77	}
